1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * SHA-256 helper used to derive an owner's {@code customerCode} hash segment. Pinned so both the
10	 * Spring and OfficeFloor arms produce identical values: the digest is taken over the UTF-8 bytes and
11	 * rendered as lower-case hex, from which callers take the leading, upper-cased characters.
12	 *
13	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
14	 * expose exactly one public method.
15	 */
16	public final class Hashes {
17	
18	    private Hashes() {
19	    }
20	
21	    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
22	    public static String sha256Hex(String s) {
23	        try {
24	            byte[] digest = MessageDigest.getInstance("SHA-256")
25	                    .digest(s.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder sb = new StringBuilder(digest.length * 2);
27	            for (byte b : digest) {
28	                sb.append(String.format("%02x", b));
29	            }
30	            return sb.toString();
31	        }
32	        catch (NoSuchAlgorithmException ex) {
33	            throw new IllegalStateException("SHA-256 not available", ex);
34	        }
35	    }
36	
37	    /** The first {@code n} upper-case hex characters of SHA-256 over {@code s}. */
38	    public static String sha256UpperHex(String s, int n) {
39	        return sha256Hex(s).substring(0, n).toUpperCase(Locale.ROOT);
40	    }
41	}
