1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	/**
4	 * Computes a single Luhn check digit over the digits contained in a string. Used to derive an
5	 * owner's {@code checkDigit} from their customerCode. The algorithm is the standard Luhn
6	 * (right-to-left doubling of alternate digits); non-digit characters are ignored, so separators
7	 * such as the '-' in a customerCode do not affect the result. Pinned so both the Spring and
8	 * OfficeFloor arms produce identical values.
9	 */
10	public final class Luhn {
11	
12	    private Luhn() {
13	    }
14	
15	    /** The Luhn check digit (0-9) over the digits contained in {@code s}; non-digits are ignored. */
16	    public static int checkDigit(String s) {
17	        int sum = 0;
18	        boolean dbl = true;
19	        for (int i = s.length() - 1; i >= 0; i--) {
20	            char c = s.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (dbl) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
30	            }
31	            sum += d;
32	            dbl = !dbl;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
