8	/**
9	 * Assigns the owner's {@code namesakeCount} — the number of existing owners (before
10	 * this create) sharing the same {@code firstName} and {@code lastName}, compared
11	 * case-insensitively.
12	 */
13	public class AssignOwnerNamesakeCount {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = owner.getFirstName();
17	        String lastName = owner.getLastName();
18	        long count = ownerRepository.findAll().stream()
19	                .filter(existing -> Strings.equalsIgnoreCase(existing.getFirstName(), firstName)
20	                        && Strings.equalsIgnoreCase(existing.getLastName(), lastName))
21	                .count();
22	        owner.setNamesakeCount((int) count);
23	    }
